import json

from google.cloud import monitoring_v3

def metric_summary(payload, config=None):
    config = config or {}
    client = monitoring_v3.MetricServiceClient()
    series = client.list_time_series(request={"name": f"projects/{config['project_id']}",
        "filter": "metric.type = " + json.dumps(payload["metric"]),
        "interval": {"start_time": {"seconds": int(payload["start_time"])},
                      "end_time": {"seconds": int(payload["end_time"])}},
        "aggregation": {"alignment_period": {"seconds": config.get("period_seconds", 60)},
                          "per_series_aligner": monitoring_v3.Aggregation.Aligner.ALIGN_MEAN},
        "view": monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL})
    points = []
    for timeseries in series:
        for point in timeseries.points:
            kind = point.value._pb.WhichOneof("value")
            if kind not in ("double_value", "int64_value"):
                raise ValueError("Expected a scalar numeric metric")
            points.append({"timestamp": point.interval.end_time.timestamp(), "value": float(getattr(point.value, kind))})
    return {"summary": {"trend": "increasing" if points and points[-1]["value"] > points[0]["value"] else "decreasing" if points and points[-1]["value"] < points[0]["value"] else "stable", "anomaly": "detected" if points and abs(points[-1]["value"] - points[0]["value"]) > 10 else "none"}}

import re

def metric_annotation_safety(annotation):
    unsafe_patterns = [r'<script>', r'<style>', r'<iframe>', r'<object>', r'<embed>', r'<applet>']
    for pattern in unsafe_patterns:
        if re.search(pattern, annotation):
            return False
    return True

import os
import json

from google.cloud import storage

def metrics_export_archive(payload, config=None):
    config = config or {}
    client = storage.Client()
    bucket = client.get_bucket(config['bucket_name'])
    blob = bucket.blob(f"metrics/{payload['metric']}/{payload['timestamp']}.json")
    blob.upload_from_string(json.dumps(payload['data']), content_type='application/json')
    return {"status": "success"}
